<template><el-dialog v-model="visible" title="资料附件库" width="min(1100px,calc(100vw - 32px))" append-to-body destroy-on-close @closed="close">
 <el-alert title="PDF / DOCX / XLSX / UTF-8 TXT / ZIP，每个不超过20MiB；旧DOC/XLS和含宏文档不支持。附件默认私有，只有发布资料后才公开；不要上传密钥、个人隐私或其他保密材料。" :closable="false"/>
 <el-form inline style="margin-top:12px" @submit.prevent="search"><el-form-item label="文件名前缀"><el-input v-model="q.name" maxlength="160" clearable/></el-form-item><el-button @click="search">查询</el-button><el-button v-hasPermi="['cms:download:upload']" type="primary" :loading="busy" @click="input.click()">上传附件</el-button><input ref="input" type="file" accept=".pdf,.docx,.xlsx,.txt,.zip" hidden @change="upload"/></el-form>
 <el-table :data="rows" v-loading="loading"><el-table-column prop="fileId" label="编号" width="80"/><el-table-column prop="name" label="文件名" min-width="200"/><el-table-column prop="extension" label="类型" width="90"/><el-table-column label="大小" width="110"><template #default="s">{{(s.row.byteSize/1024).toFixed(1)}} KiB</template></el-table-column><el-table-column prop="sha256" label="SHA256" show-overflow-tooltip/><el-table-column label="操作" min-width="170"><template #default="s"><el-button v-if="selecting" type="primary" link @click="select(s.row)">使用此附件</el-button><el-button link @click="download(s.row)">下载</el-button><el-button v-hasPermi="['cms:download:fileRemove']" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table>
 <pagination v-if="total" :total="total" v-model:page="q.pageNum" v-model:limit="q.pageSize" @pagination="load"/><p>资料草稿、当前公开版、历史修订都算引用。被引用的附件不能物理删除；先下架资料仅停止公开访问。</p>
</el-dialog></template>
<script setup>
import{ref,reactive,onBeforeUnmount,onDeactivated}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{saveAs}from'file-saver';import request from'@/utils/request';import{workflow}from'@/api/cms/workflow'
const emit=defineEmits(['selected']),visible=ref(false),selecting=ref(false),rows=ref([]),total=ref(0),loading=ref(false),busy=ref(false),input=ref(),q=reactive({name:'',pageNum:1,pageSize:10});let epoch=0
async function load(){const n=++epoch;loading.value=true;try{const r=await workflow('download/files','get',undefined,{...q});if(n===epoch){rows.value=r.rows;total.value=r.total}}finally{if(n===epoch)loading.value=false}}
function open(choose=false){selecting.value=choose;visible.value=true;q.pageNum=1;load()}function search(){q.pageNum=1;load()}function select(row){emit('selected',row);visible.value=false}
async function upload(event){const file=event.target.files?.[0];event.target.value='';if(!file||busy.value)return;if(file.size===0||file.size>20*1024*1024){ElMessage.warning('文件必须非空且不超过20MiB');return};const n=epoch;busy.value=true;try{const data=new FormData();data.append('file',file);await request({url:'/cms/download/files/upload',method:'post',data,headers:{'Content-Type':'multipart/form-data',repeatSubmit:false},timeout:30000});if(n!==epoch)return;ElMessage.success('已上传为私有附件');q.pageNum=1;await load()}finally{busy.value=false}}
async function download(row){const n=epoch,b=await request({url:`/cms/download/files/${row.fileId}/file`,responseType:'blob',timeout:30000});if(n!==epoch)return;if(b.type.includes('json')){ElMessage.error(JSON.parse(await b.text()).msg||'下载失败');return};saveAs(b,row.name)}
async function remove(row){const n=epoch;try{await ElMessageBox.confirm('仅无任何草稿或历史引用的附件可以删除，确认？','删除资料附件',{type:'warning'});if(n!==epoch)return;await workflow(`download/files/${row.fileId}`,'delete',{version:row.version});await load()}catch{}}
function close(){++epoch;visible.value=false;rows.value=[];loading.value=false}onBeforeUnmount(close);onDeactivated(close);defineExpose({open,close})
</script>
